import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            # For clinical features, use t-test
            y0 = feats.x[feats.y == 0, i]
            y1 = feats.x[feats.y == 1, i]
            t_stat, p_val = stats.ttest_ind(y0, y1, equal_var=False)
        else:
            # For other features, use correlation with outcome
            t_stat, p_val = stats.pearsonr(feats.x[:, i], feats.y)

        if p_val < 0.05:
            sig_features.append((fid, abs(t_stat), p_val))

    # Sort by effect size
    sig_features.sort(key=lambda x: x[1], reverse=True)

    # Group correlated features
    correlated_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                # Always put smaller id first to avoid duplicates
                if fid1 > fid2:
                    fid1, fid2 = fid2, fid1
                correlated_pairs.add((fid1, fid2))

    # Build clusters of correlated features
    clusters = []
    used = set()

    for fid1, fid2 in correlated_pairs:
        if fid1 in used or fid2 in used:
            continue

        cluster = {fid1, fid2}
        used.add(fid1)
        used.add(fid2)

        # Expand cluster
        changed = True
        while changed:
            changed = False
            for fid1_, fid2_ in correlated_pairs:
                if fid1_ in cluster or fid2_ in cluster:
                    if fid1_ not in cluster:
                        cluster.add(fid1_)
                        used.add(fid1_)
                        changed = True
                    if fid2_ not in cluster:
                        cluster.add(fid2_)
                        used.add(fid2_)
                        changed = True

        clusters.append(cluster)

    # Handle unclustered features
    unclustered = [f for f in sig_features if f[0] not in used]

    # Select best features from each cluster (prefer those with strongest associations)
    selected_drivers = []
    for cluster in clusters:
        # Find best feature in cluster based on association strength
        best_fid = None
        best_assoc = -1
        for fid in cluster:
            idx = feats.column(fid)
            if feats.types[idx] == 'clinical':
                y0 = feats.x[feats.y == 0, idx]
                y1 = feats.x[feats.y == 1, idx]
                t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
            else:
                t_stat, _ = stats.pearsonr(feats.x[:, idx], feats.y)

            if abs(t_stat) > best_assoc:
                best_assoc = abs(t_stat)
                best_fid = fid

        if best_fid:
            selected_drivers.append(best_fid)

    # Add unclustered significant features
    for fid, _, _ in unclustered[:MAX_DRIVERS - len(selected_drivers)]:
        selected_drivers.append(fid)

    # Limit to max drivers
    selected_drivers = selected_drivers[:MAX_DRIVERS]

    # If no strong drivers found, return empty design
    if not selected_drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # For products, look for interactions between top features
    products = []
    for i, fid1 in enumerate(selected_drivers):
        for j, fid2 in enumerate(selected_drivers[i+1:], i+1):
            products.append((fid1, fid2))

    # Use all selected features for regression
    columns = tuple(selected_drivers)

    # Create loadings for weighted score
    loadings = {}
    for fid in selected_drivers:
        idx = feats.column(fid)
        if feats.types[idx] == 'clinical':
            y0 = feats.x[feats.y == 0, idx]
            y1 = feats.x[feats.y == 1, idx]
            t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
        else:
            t_stat, _ = stats.pearsonr(feats.x[:, idx], feats.y)
        loadings[fid] = t_stat

    return Design(drivers=tuple(selected_drivers), columns=columns, products=tuple(products), loadings=loadings)

